-- Seed data restored from the Bureau's 2517 fiscal-year ledger (2500_ECODOC spreadsheet).
-- Every headline economic and demographic figure is the exact value on file for that year.
-- USA's revenue (only) is filled in from its own GMing_calculator detail sheet (2508 figure,
-- carried forward per instruction) since the master 2517 ledger left it blank; USA's
-- expenditures remain unset since no source gives a real figure for it.
-- Currency names/symbols are left unset here, exactly as a freshly-registered nation would be --
-- the ledger never recorded each nation's real currency name, only a shared reference ("C$")
-- used purely for calculation. Set each nation's real currency from its panel as usual; the
-- existing currency_group already mirrors the app's own subdivision-inherits-parent convention,
-- so setting a sovereign's currency will cascade to its subdivisions immediately, same as always.
-- Fiscal parameters (LVT rates, tax brackets, custom Bureau variables) are NOT seeded here --
-- set those per nation from the GM Formula Workbench after this runs.

  ON CONFLICT (id) DO UPDATE SET current_year = EXCLUDED.current_year;


ON CONFLICT (acronym) DO UPDATE SET
  name = EXCLUDED.name,
  parent_acronym = EXCLUDED.parent_acronym,
  sort_order = EXCLUDED.sort_order,
  currency_group = EXCLUDED.currency_group,
  currency_name = EXCLUDED.currency_name,
  currency_symbol = EXCLUDED.currency_symbol,
  inflation_rate = EXCLUDED.inflation_rate,
  inflation_ratio = EXCLUDED.inflation_ratio,
  ppp_conversion = EXCLUDED.ppp_conversion,
  gdp_nominal = EXCLUDED.gdp_nominal,
  gdp_real = EXCLUDED.gdp_real,
  gdp_ppp = EXCLUDED.gdp_ppp,
  growth_rate = EXCLUDED.growth_rate,
  revenue = EXCLUDED.revenue,
  expenditures = EXCLUDED.expenditures,
  net_income = EXCLUDED.net_income,
  treasury = EXCLUDED.treasury,
  debt = EXCLUDED.debt,
  population = EXCLUDED.population,
  pop_growth = EXCLUDED.pop_growth,
  migration = EXCLUDED.migration,
  debt_treasury_ratio = EXCLUDED.debt_treasury_ratio,
  revenue_gdp_ratio = EXCLUDED.revenue_gdp_ratio,
  credit_rating = EXCLUDED.credit_rating,
  body = EXCLUDED.body,
  expenditure_items = EXCLUDED.expenditure_items;